-- Accept each captured old or new row independently, including a known partial state.
-- Guard all writes even under mysql --force. The lock also covers the MyISAM tables.
SET NAMES utf8;
CREATE TEMPORARY TABLE `grilek_guard` (`ok` TINYINT NOT NULL PRIMARY KEY) ENGINE=MEMORY;
INSERT INTO `grilek_guard` VALUES (1);
LOCK TABLES `creature_template` WRITE, `creature_ai_scripts` WRITE, `creature_immunities` WRITE, `spell_scripts` WRITE, `gameobject_template` WRITE, `dbscripts_on_go_template_use` WRITE, `game_event` WRITE, `game_event_time` WRITE;
SET @grilek_ok = 1;

